#include<bits/stdc++.h>
using namespace std;
int n, k;
int a[15];
int group_sum[15];
int ans[15];
int target;

bool solve(int i) {
    if (i == n) {
        for (int g = 1; g <= k; g++) if (group_sum[g] == 0) return false;
        return true;
    }
    for (int g = 1; g <= k; g++) {
        if (group_sum[g] + a[i] <= target) {
            group_sum[g] += a[i];
            ans[i] = g;
            if (solve(i + 1)) return true;
            group_sum[g] -= a[i];
        }
        if (group_sum[g] == 0) break;
    }
    return false;
}

int main() {
    if (!(cin >> n >> k)) return 0;
    int sum = 0;
    for (int i = 0; i < n; i++) {
        cin >> a[i];
        sum += a[i];
    }
    if (sum % k != 0) {
        cout << "ze\n";
        return 0;
    }
    target = sum / k;
    if (solve(0)) {
        for (int i = 0; i < n; i++) cout << ans[i] << (i == n - 1 ? "" : " ");
        cout << '\n';
    } else {
        cout << "ze\n";
    }
}

