    if (!(cin >> n)) return 0;
    vector<int> a(n);
    for (int i=0; i<n; i++) {
        string s; cin >> s;
        int mask = 0;
        for (char c : s) mask |= (1 << (c - 'a'));
        a[i] = mask;
    }

    int n1 = n / 2;
    int n2 = n - n1;
    unordered_map<int, long long> m1, m2;
    for (int i = 0; i < (1 << n1); i++) {
        int mask = 0;
        for (int j = 0; j < n1; j++) if (i & (1 << j)) mask |= a[j];
        m1[mask]++;
    }
    for (int i = 0; i < (1 << n2); i++) {
        int mask = 0;
        for (int j = 0; j < n2; j++) if (i & (1 << j)) mask |= a[n1 + j];
        m2[mask]++;
    }

    vector<pair<int, long long>> v2(m2.begin(), m2.end());
    long long ans = 0;
    int target = (1 << 26) - 1;
    for (auto& p1 : m1) {
        int req = target ^ (p1.first & target);
        for (auto& p2 : v2) {
            if ((p2.first & req) == req) {
                ans += p1.second * p2.second;
            }
        }
    }
