#include<bits/stdc++.h>
using namespace std;

int n;
long long m;
vector<long long> a;
long long ans = 0;

void solve(int idx, long long current_term, long long total_sum) {
    if (idx == n) {
        long long final_val = (total_sum + current_term) % m;
        if (final_val < 0) final_val += m;
        if (final_val == 0) ans++;
        return;
    }
    long long val = a[idx] % m;
    // +
    solve(idx + 1, val, (total_sum + current_term) % m);
    // -
    solve(idx + 1, -val, (total_sum + current_term) % m);
    // *
    solve(idx + 1, (current_term * val) % m, total_sum);
}

void run_case() {
    cin >> n >> m;
    a.resize(n);
    for(int i=0; i<n; i++) cin >> a[i];
    ans = 0;
    solve(1, a[0] % m, 0);
    cout << ans << '\n';
}

int main() {
    int t;
    if (cin >> t) {
        while(t--) run_case();
    }
}

